insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_5_v1'
from (values
('114.41.c.1.A',3,'At Level III a student answers a question about a topic beyond daily routines, such as a school trip abroad, and adds details. This is:','["going beyond everyday topics with elaboration", "repeating a memorized phrase", "avoiding the topic", "answering yes or no only"]'::jsonb,0,'Level III extends past everyday life with simple elaboration.','original'),
('114.41.c.1.A',3,'Which response goes beyond everyday life with elaboration?','["Yes.", "I would like to visit a museum because I enjoy history, and the exhibits change every month.", "I do not know.", "Museum."]'::jsonb,1,'Elaboration adds reasons and details.','original'),
('114.41.c.1.B',3,'Giving a recommendation, such as suggesting a book and explaining why, is part of:','["completing a lab", "filling in a form", "exchanging opinions and recommendations", "reading a map"]'::jsonb,2,'Recommendations include supporting statements.','original'),
('114.41.c.1.B',3,'Which statement includes a recommendation with support?','["Park.", "The park is a place.", "I like it.", "I recommend the park because it is quiet and has shade."]'::jsonb,3,'A recommendation includes a reason.','original'),
('114.41.c.1.C',3,'A speaker says, You must study tonight because the test counts for a quarter of your grade. The speaker is:','["telling what someone must do with a reason", "asking a favor", "describing weather", "telling a joke"]'::jsonb,0,'Obligation is paired with a reason.','original'),
('114.41.c.1.C',3,'In written conversation, how can a student give advice with supporting reasons?','["by drawing a map", "by writing what the friend should do and why", "by listing random facts", "by copying a headline"]'::jsonb,1,'Advice includes reasons.','original'),
('114.41.c.1.D',3,'Which sentence offers a suggestion and a supporting statement?','["We finish.", "Meet.", "Let''s meet earlier so we have time to finish the poster.", "Poster."]'::jsonb,2,'Suggestions are followed by reasons.','original'),
('114.41.c.1.D',3,'Developing a plan in conversation means the speakers:','["list unrelated items", "avoid decisions", "argue without conclusion", "decide together what to do, when and how"]'::jsonb,3,'Plans involve shared decisions.','original'),
('114.41.c.1.E',3,'Reacting appropriately in conversation includes:','["using register and gestures that fit the culture", "using the same expression for everyone", "speaking as fast as possible", "ignoring the listener"]'::jsonb,0,'Reactions follow cultural norms.','original'),
('114.41.c.1.E',3,'Switching from casual talk with a friend to a more formal tone with a principal shows control of:','["punctuation only", "register", "alphabet", "spelling"]'::jsonb,1,'Register adapts to the listener.','original'),
('114.41.c.1.F',3,'A written reply to a friend''s message should reflect:','["complete silence", "random words", "culturally appropriate expressions and style", "only abbreviations"]'::jsonb,2,'Writing style fits audience and culture.','original'),
('114.41.c.1.F',3,'Which closing suits a formal email to a school director?','["Whatever", "See ya", "Bye bye", "With respect, followed by your full name"]'::jsonb,3,'Formal closings fit formal contexts.','original'),
('114.41.c.2.A',3,'Understanding a podcast made for native speakers shows a learner can work with:','["authentic audio material", "only textbook charts", "only handwriting", "only teacher-made drills"]'::jsonb,0,'Authentic material is made for speakers of the language.','original'),
('114.41.c.2.A',3,'A learner reads a news website from another country. This is:','["a fill-in-the-blank quiz", "authentic digital material", "a worksheet", "a coloring page"]'::jsonb,1,'Digital content from speakers is authentic.','original'),
('114.41.c.2.B',3,'To paraphrase the main idea of a short film, a learner should:','["list actors only", "copy the subtitles", "restate the idea in different words", "skip to the credits"]'::jsonb,2,'Paraphrasing shows understanding.','original'),
('114.41.c.2.B',3,'Which is a supporting detail in a story about a market day?','["the font size", "the date of printing", "the title of the document", "what vendors sold and how the crowd reacted"]'::jsonb,3,'Details support the main idea.','original'),
('114.41.c.2.C',3,'A learner meets a new word in a contextualized video. The best approach is to:','["use surrounding images and words to infer meaning", "ignore the video", "guess randomly", "stop immediately"]'::jsonb,0,'Inference uses context.','original'),
('114.41.c.2.C',3,'Which clue helps infer meaning of an unfamiliar phrase in a conversation?','["the page number", "the speaker''s tone and the situation", "the font", "the weather report"]'::jsonb,1,'Tone and situation give clues.','original'),
('114.41.c.2.D',3,'Comparing how families celebrate a holiday in two cultures is:','["contrasting spelling rules", "measuring distances", "contrasting cultural practices", "comparing math results"]'::jsonb,2,'Practices are compared across cultures.','original'),
('114.41.c.2.D',3,'After watching two videos of school life in different countries, a learner notes both similarities and differences. This is:','["avoiding the topic", "ignoring details", "copying vocabulary", "comparing and contrasting cultural practices"]'::jsonb,3,'Comparison involves likeness and difference.','original'),
('114.41.c.3.A',3,'Defending an opinion in a speech means:','["giving reasons and examples to support it", "avoiding any reasons", "changing it constantly", "repeating it quietly"]'::jsonb,0,'Defending adds support.','original'),
('114.41.c.3.A',3,'Which written opinion includes support and elaboration?','["Students.", "I believe students need more sleep because tired students learn less, and many schools start too early.", "Sleep.", "I believe."]'::jsonb,1,'Elaboration strengthens opinions.','original'),
('114.41.c.3.B',3,'Narrating an event with connected sentences, details and elaboration means telling it:','["in a single sentence", "with no details", "in order with specific information", "as a list of words"]'::jsonb,2,'Narration needs sequence and detail.','original'),
('114.41.c.3.B',3,'Which sentence helps narrate an event with detail?','["Hike.", "Deer.", "River.", "Last Saturday, we hiked a trail near the river and saw three deer."]'::jsonb,3,'Specific details enrich narration.','original'),
('114.41.c.3.C',3,'Informing others about a topic in writing at Level III includes:','["connected sentences with details", "one-word answers", "a single phrase", "only a title"]'::jsonb,0,'Informative writing connects sentences and details.','original'),
('114.41.c.3.C',3,'Which task is an example of informing others orally?','["drawing a map", "giving a short talk on how a local festival began", "silently reading", "copying a recipe"]'::jsonb,1,'Informing explains facts to an audience.','original'),
('114.42.c.1.A',4,'At Level IV a student answers a question about an event outside daily routine with elaboration. This shows:','["memorized scripts only", "single-word answers", "elaboration beyond everyday topics", "avoidance"]'::jsonb,2,'Level IV elaborates on varied topics.','original'),
('114.42.c.1.A',4,'Which response shows elaboration at Level IV?','["It is.", "Yes.", "Maybe.", "I think public transportation helps cities because it reduces traffic and pollution."]'::jsonb,3,'Elaboration includes reasons.','original'),
('114.42.c.1.B',4,'Responding to a question in an unfamiliar context with limited vocabulary requires the student to:','["use circumlocution and clarifying strategies", "stop speaking", "ignore the question", "switch to another subject"]'::jsonb,0,'Strategies help in unfamiliar situations.','original'),
('114.42.c.1.B',4,'A student does not know a word and describes it with other words instead. This strategy is:','["spelling", "circumlocution", "silence", "copying"]'::jsonb,1,'Circumlocution means talking around a word.','original'),
('114.42.c.1.C',4,'Exchanging opinions and recommendations at Level IV includes:','["one-word replies", "copied sentences", "supporting elaborative statements", "unrelated jokes"]'::jsonb,2,'Elaborative support deepens exchange.','original'),
('114.42.c.1.C',4,'Which pair shows an opinion with elaborative support?','["Plan.", "I do not know.", "Yes. Plan.", "I prefer the first plan. It is cheaper, and it needs less time."]'::jsonb,3,'Support follows the opinion.','original'),
('114.42.c.1.D',4,'Telling someone what they must do using detailed rationale means:','["explaining the reasons behind the instruction", "using one word", "giving only commands", "avoiding reasons"]'::jsonb,0,'Rationale explains why.','original'),
('114.42.c.1.D',4,'Which statement gives a detailed rationale?','["Helmet.", "You should wear a helmet since it protects your head and many local rules require it.", "Do it.", "Wear it."]'::jsonb,1,'Rationale supports the advice.','original'),
('114.42.c.1.E',4,'Articulating requests, offering suggestions and developing plans with elaborative statements shows:','["silence", "scripted lines", "extended planning conversation", "a single request"]'::jsonb,2,'Plans involve extended talk.','original'),
('114.42.c.1.E',4,'A student proposes, Let''s hold the fundraiser in spring since the weather is better and more families can attend. This is:','["a greeting", "a refusal", "a question only", "a suggestion with elaboration"]'::jsonb,3,'The suggestion has reasons.','original'),
('114.42.c.1.F',4,'Interacting and reacting in spoken conversation with culturally appropriate gestures shows:','["sociolinguistic awareness", "only reading skill", "only memorized scripts", "only writing skill"]'::jsonb,0,'Appropriate gestures show cultural awareness.','original'),
('114.42.c.1.F',4,'A student shifts register when speaking with an elder versus a peer. This demonstrates:','["confusion", "cultural appropriateness", "guessing", "avoidance"]'::jsonb,1,'Register choice respects culture.','original'),
('114.42.c.1.G',4,'In a written exchange with a pen pal, a student''s response should:','["copy the pen pal''s message", "use only symbols", "address the pen pal''s points in an appropriate style", "ignore the content"]'::jsonb,2,'Interactive writing responds to the other person.','original'),
('114.42.c.1.G',4,'Which element reflects culturally appropriate written style in an email to an official?','["emojis only", "no greeting", "slang", "a formal greeting and closing"]'::jsonb,3,'Formal contexts need formal style.','original'),
('114.42.c.2.A',4,'Analyzing a culturally authentic documentary requires a learner to:','["look at content, perspective and cultural context", "skip the middle", "memorize the title", "watch with the sound off"]'::jsonb,0,'Analysis considers context.','original'),
('114.42.c.2.A',4,'Which material would a Level IV student analyze in a variety of contexts?','["a spelling list", "an article or video made for speakers of the language", "a teacher-made worksheet", "a blank grid"]'::jsonb,1,'Authentic materials are the basis of analysis.','original'),
('114.42.c.2.B',4,'To paraphrase and analyze a text''s theme, a learner:','["lists unrelated facts", "skips details", "restates the central idea and explains how details support it", "copies the title"]'::jsonb,2,'Analysis connects theme and details.','original'),
('114.42.c.2.B',4,'Which is an analysis of supporting details?','["naming the author", "copying a quote", "counting pages", "explaining how examples in a story develop its message"]'::jsonb,3,'Analysis explains how details work.','original'),
('114.42.c.2.C',4,'Inferring meaning of unfamiliar words in a text relies on:','["context, word parts and prior knowledge", "ignoring clues", "the font", "random guessing"]'::jsonb,0,'Inference uses multiple clues.','original'),
('114.42.c.2.C',4,'A learner knows a prefix and root in a new word. Using them to guess the meaning is:','["a copying task", "an inference strategy", "a spelling error", "a pronunciation exercise"]'::jsonb,1,'Word parts help inference.','original'),
('114.42.c.2.D',4,'Comparing perspectives on a historic event from two authentic sources is:','["copying captions", "measuring angles", "contrasting cultural practices and perspectives", "naming rivers"]'::jsonb,2,'Perspective comparison is a Level IV skill.','original'),
('114.42.c.2.D',4,'Why do perspectives from two cultures about the same holiday sometimes differ?','["because there are no values", "because holidays are random", "because languages are identical", "because history and values shape how a group sees an event"]'::jsonb,3,'Perspectives reflect culture.','original'),
('114.42.c.3.A',4,'Persuading others in a speech involves:','["claims, support and elaborative statements", "unrelated stories", "one-word answers", "silence"]'::jsonb,0,'Persuasion uses claims and support.','original'),
('114.42.c.3.A',4,'Which opening is most persuasive?','["We have gardens.", "Our school needs a garden because it teaches science and builds community.", "Garden.", "Gardens are green."]'::jsonb,1,'Persuasion states a claim with reasons.','original'),
('114.42.c.3.B',4,'Narrating with some connected discourse means the narrator:','["uses only one word", "speaks in fragments", "links sentences with transitions and details", "lists events with no links"]'::jsonb,2,'Connected discourse flows.','original'),
('114.42.c.3.B',4,'Which phrase signals a transition in a narrative?','["blue sky", "a red shoe", "the number five", "after that, later on"]'::jsonb,3,'Transitions connect events.','original'),
('114.42.c.3.C',4,'Informing others about a topic with some connected discourse requires:','["organized paragraphs with transitions", "one phrase", "bullet fragments only", "a title only"]'::jsonb,0,'Organization supports information.','original'),
('114.42.c.3.C',4,'Which is a strong way to inform an audience about recycling?','["avoid explaining", "give facts, examples and clear connections between them", "recite a single word", "draw without text"]'::jsonb,1,'Information needs clear connections.','original'),
('114.43.c.1.A',4,'Using generally consistent register in all time frames means a speaker:','["only speaks about the present", "avoids time references", "keeps an appropriate tone while talking about past, present and future", "changes tone randomly"]'::jsonb,2,'Register stays consistent across time frames.','original'),
('114.43.c.1.A',4,'Which skill separates Level V conversation from earlier levels?','["using only memorized lines", "answering yes or no", "avoiding abstract topics", "sustaining discussion across past, present and future"]'::jsonb,3,'Level V handles all time frames.','original'),
('114.43.c.1.B',4,'Verbally exchanging information on a variety of geographic, cultural and academic topics requires:','["broad vocabulary and appropriate register", "only greetings", "only numbers", "only names"]'::jsonb,0,'Broad topics require broad language.','original'),
('114.43.c.1.B',4,'A student discusses climate in one region and economic trends in another. This shows:','["a single-topic script", "ability to exchange information on varied topics", "silence", "random chatter"]'::jsonb,1,'Variety of topics is a Level V goal.','original'),
('114.43.c.1.C',4,'Writing a business-style letter that keeps a formal register across time frames shows:','["copied phrases", "only informal slang", "consistent register in writing", "inconsistent tone"]'::jsonb,2,'Written register is consistent.','original'),
('114.43.c.1.C',4,'Which written item might a Level V student produce with consistent register?','["a drawing", "a list of single words", "a grocery list only", "a formal letter of inquiry"]'::jsonb,3,'Correspondence uses consistent register.','original'),
('114.43.c.1.D',4,'A written exchange that provides information on a topic of interest reflects:','["clear, organized, detailed writing", "fragmented notes", "silent reading", "unrelated sentences"]'::jsonb,0,'Written exchanges present information.','original'),
('114.43.c.1.D',4,'Which written response keeps register consistent with a formal reader?','["a single emoji", "a polished message with appropriate vocabulary and closing", "a casual text with slang", "a note without greeting"]'::jsonb,1,'Register must fit the reader.','original'),
('114.43.c.2.A',4,'Reading and analyzing artwork or a news article from the target culture requires:','["reading the last line only", "only skimming the title", "attention to content, context and perspective", "ignoring images"]'::jsonb,2,'Analysis uses multiple layers.','original'),
('114.43.c.2.A',4,'Which resource might a Level V learner analyze?','["an alphabet chart", "a teacher quiz", "a blank page", "a magazine, an artwork description or a government website in the target language"]'::jsonb,3,'Authentic resources are the basis of analysis.','original'),
('114.43.c.2.B',4,'Comparing cultural perspectives from authentic print sources means:','["examining how viewpoints differ and why", "copying passages", "listing page numbers", "skipping context"]'::jsonb,0,'Perspective comparison is analytic.','original'),
('114.43.c.2.B',4,'Why analyze cultural practices alongside perspectives?','["perspectives do not matter", "practices reflect the values behind them", "practices are unrelated to values", "analysis is optional"]'::jsonb,1,'Practices and perspectives are linked.','original'),
('114.43.c.2.C',4,'Listening to an interview made for native speakers and explaining its main points shows:','["note copying", "ignoring the audio", "analysis of authentic audio", "reading only"]'::jsonb,2,'Audio analysis requires comprehension.','original'),
('114.43.c.2.C',4,'Which strategy helps analyze a rapid audio recording?','["only counting words", "ignoring the speaker", "turning off the sound", "listening for tone, key terms and structure"]'::jsonb,3,'Analysis uses multiple cues.','original'),
('114.43.c.2.D',4,'Analyzing cultural perspectives in an audiovisual documentary means identifying:','["the viewpoint of the creators and the audience", "the file format", "only the credits", "only the length"]'::jsonb,0,'Perspective analysis considers creators.','original'),
('114.43.c.2.D',4,'Comparing a documentary from one culture with a film from another reveals:','["identical content", "differences in values, practices and storytelling", "nothing at all", "no difference"]'::jsonb,1,'Comparison highlights difference.','original'),
('114.43.c.3.A',4,'Planning, producing and presenting a spoken presentation with some ease and clarity means:','["avoiding the audience", "reading unrelated notes", "organizing ideas and delivering them clearly", "speaking without plan"]'::jsonb,2,'Planning and delivery matter.','original'),
('114.43.c.3.A',4,'A Level V presenter prepares an outline, practices and speaks to an audience. This is:','["silent reading", "copying text", "random speaking", "presentational communication"]'::jsonb,3,'Presentations are planned for an audience.','original'),
('114.43.c.3.B',4,'Planning and producing a written presentation such as an article with clear expression requires:','["drafting, revising and organizing ideas", "one-word answers", "copying others", "skipping planning"]'::jsonb,0,'Written work is drafted and revised.','original'),
('114.43.c.3.B',4,'Which stage improves the clarity of a written presentation?','["deleting content", "revising and editing for organization and word choice", "ignoring errors", "adding unrelated text"]'::jsonb,1,'Revision improves clarity.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
